item.content:encoded:
.site-logo a.navbar-brand img {
    filter: contrast(0) brightness(0);
}
.dark .site-logo a.navbar-brand img {
    filter: unset;
}
footer.one .site-branding-text {
    display: none;
}

.footer-logo .site-logo .navbar-brand {
    background-image: url('https://demos.themeansar.com/blogarise/blogbrute/wp-content/uploads/2026/07/logo-white-1.png');
    width: 270px;
    display: block;
    background-repeat: no-repeat;
    height: 120px;
    background-size: contain;
    background-position: center;
}
